        labels.append(data[offset:offset+l].decode())
        offset += l
    return '.'.join(labels)+'.', (start if jumped else offset)


def encode_name(name):
    if name == '.':
        return b'\x00'
    out=b''
    for label in name.rstrip('.').split('.'):
        out += bytes([len(label)]) + label.encode()
    return out + b'\x00'


def rr(name, rtype, ttl, rdata, rclass=1):
    return encode_name(name) + struct.pack('!HHIH', rtype, rclass, ttl, len(rdata)) + rdata


