#!/usr/bin/env python3

from __future__ import annotations

import json
import os
import random
import socket
import ssl
import struct
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Iterable


HELP_TEXT = """dog ● command-line DNS client

Usage:
  dog [OPTIONS] [--] <arguments>

Examples:
  dog example.net                          Query a domain using default settings
  dog example.net MX                       ...looking up MX records instead
  dog example.net MX @1.1.1.1              ...using a specific nameserver instead
  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP
  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments

Query options:
  <arguments>              Human-readable host names, nameservers, types, or classes
  -q, --query=HOST         Host name or domain name to query
  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)
  -n, --nameserver=ADDR    Address of the nameserver to send packets to
  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)

Sending options:
  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)
  --txid=NUMBER            Set the transaction ID to a specific value
  -Z=TWEAKS                Set uncommon protocol-level tweaks

Protocol options:
  -U, --udp                Use the DNS protocol over UDP
  -T, --tcp                Use the DNS protocol over TCP
  -S, --tls                Use the DNS-over-TLS protocol
  -H, --https              Use the DNS-over-HTTPS protocol

Output options:
  -1, --short              Short mode: display nothing but the first result
  -J, --json               Display the output as JSON
  --color, --colour=WHEN   When to colourise the output (always, automatic, never)
  --seconds                Do not format durations, display them as seconds
  --time                   Print how long the response took to arrive

Meta options:
  -?, --help               Print list of command-line options
  -v, --version            Print version information"""

VERSION_TEXT = """dog ● command-line DNS client
v0.2.0-pre [d3a34280] built on 2026-04-17 (pre-release!)
mhttps://dns.lookup.dog/"""

TYPE_BY_NAME = {
    "A": 1,
    "NS": 2,
    "CNAME": 5,
    "SOA": 6,
    "PTR": 12,
    "HINFO": 13,
    "MX": 15,
    "TXT": 16,
    "AFSDB": 18,
    "AAAA": 28,
    "LOC": 29,
    "SRV": 33,
    "NAPTR": 35,
    "OPT": 41,
    "SSHFP": 44,
    "TLSA": 52,
    "IXFR": 251,
    "AXFR": 252,
    "ANY": 255,
    "CAA": 257,
}
TYPE_NAME_BY_CODE = {value: key for key, value in TYPE_BY_NAME.items()}
DISPLAY_TYPE_NAME_BY_CODE = dict(TYPE_NAME_BY_CODE)

CLASS_BY_NAME = {
    "IN": 1,
    "CH": 3,
    "HS": 4,
}
CLASS_NAME_BY_CODE = {value: key for key, value in CLASS_BY_NAME.items()}

RCODE_TEXT = {
    1: "Format Error",
    2: "Server Failure",
    3: "NXDomain",
    4: "Not Implemented",
    5: "Refused",
}


class DogError(Exception):
    pass


class InvalidOptions(DogError):
    pass


class SystemResolverError(DogError):
    pass


class NetworkFailure(DogError):
    pass


@dataclass
class ProtocolTweaks:
    aa: bool = False
    ad: bool = False
    cd: bool = False
    bufsize: int | None = None


@dataclass
class Config:
    queries: list[str] = field(default_factory=list)
    qtypes: list[int] = field(default_factory=list)
    qclasses: list[int] = field(default_factory=list)
    nameservers: list[str] = field(default_factory=list)
    edns: str = "hide"
    txid: int | None = None
    tweaks: ProtocolTweaks = field(default_factory=ProtocolTweaks)
    transport: str = "udp"
    force_udp: bool = False
    short: bool = False
    as_json: bool = False
    colour: str = "automatic"
    seconds: bool = False
    show_time: bool = False
    show_help: bool = False
    show_version: bool = False


@dataclass
class DNSHeader:
    ident: int
    flags: int
    qdcount: int
    ancount: int
    nscount: int
    arcount: int

    @property
    def rcode(self) -> int:
        return self.flags & 0x000F

    @property
    def truncated(self) -> bool:
        return bool(self.flags & 0x0200)


@dataclass
class DNSQuestion:
    name: str
    qclass: int
    qtype: int


@dataclass
class DNSRecord:
    name: str
    rtype: int
    rclass: int
    ttl: int
    raw_rdata: bytes
    parsed: Any


@dataclass
class DNSResponse:
    header: DNSHeader
    questions: list[DNSQuestion]
    answers: list[DNSRecord]
    authorities: list[DNSRecord]
    additionals: list[DNSRecord]


def print_help() -> None:
    print(HELP_TEXT)


def print_version() -> None:
    print(VERSION_TEXT)


def parse_uint16(text: str) -> int:
    try:
        value = int(text, 10)
    except ValueError as exc:
        raise InvalidOptions(f'Invalid transaction ID "{text}"') from exc
    if not 0 <= value <= 0xFFFF:
        raise InvalidOptions(f'Invalid transaction ID "{text}"')
    return value


def parse_type(text: str) -> int:
    key = text.upper()
    if key in TYPE_BY_NAME:
        return TYPE_BY_NAME[key]
    raise InvalidOptions(f'Invalid query type "{text}"')


def parse_class(text: str) -> int:
    key = text.upper()
    if key in CLASS_BY_NAME:
        return CLASS_BY_NAME[key]
    raise InvalidOptions(f'Invalid query class "{text}"')


def parse_protocol_tweak(text: str, tweaks: ProtocolTweaks) -> None:
    if text == "aa":
        tweaks.aa = True
        return
    if text == "ad":
        tweaks.ad = True
        return
    if text == "cd":
        tweaks.cd = True
        return
    if text.startswith("bufsize="):
        number = text.split("=", 1)[1]
        try:
            tweaks.bufsize = int(number, 10)
        except ValueError as exc:
            raise InvalidOptions(f'Invalid protocol tweak "{text}"') from exc
        return
    raise InvalidOptions(f'Invalid protocol tweak "{text}"')


def parse_edns(text: str) -> str:
    if text in {"disable", "hide", "show"}:
        return text
    raise InvalidOptions(f'Invalid EDNS setting "{text}"')


def take_value(args: list[str], index: int, current: str, inline: str | None) -> tuple[str, int]:
    if inline is not None:
        return inline, index
    if index + 1 >= len(args):
        return "", index
    return args[index + 1], index + 1


def parse_args(argv: list[str]) -> Config:
    config = Config()
    positionals: list[str] = []
    i = 0
    positional_only = False

    while i < len(argv):
        arg = argv[i]

        if positional_only:
            positionals.append(arg)
            i += 1
            continue

        if arg == "--":
            positional_only = True
            i += 1
            continue

        if arg.startswith("--"):
            name, has_value, value = arg[2:].partition("=")
            inline = value if has_value else None

            if name == "help":
                config.show_help = True
            elif name == "version":
                config.show_version = True
            elif name == "query":
                item, i = take_value(argv, i, arg, inline)
                config.queries.append(canonical_name(item))
            elif name == "type":
                item, i = take_value(argv, i, arg, inline)
                config.qtypes.append(parse_type(item))
            elif name == "nameserver":
                item, i = take_value(argv, i, arg, inline)
                config.nameservers.append(item)
            elif name == "class":
                item, i = take_value(argv, i, arg, inline)
                config.qclasses.append(parse_class(item))
            elif name == "edns":
                item, i = take_value(argv, i, arg, inline)
                config.edns = parse_edns(item)
            elif name == "txid":
                item, i = take_value(argv, i, arg, inline)
                config.txid = parse_uint16(item)
            elif name in {"color", "colour"}:
                item, i = take_value(argv, i, arg, inline)
                config.colour = item
            elif name == "udp":
                config.transport = "udp"
                config.force_udp = True
            elif name == "tcp":
                config.transport = "tcp"
                config.force_udp = False
            elif name == "tls":
                config.transport = "tls"
                config.force_udp = False
            elif name == "https":
                config.transport = "https"
                config.force_udp = False
            elif name == "short":
                config.short = True
            elif name == "json":
                config.as_json = True
            elif name == "seconds":
                config.seconds = True
            elif name == "time":
                config.show_time = True
            else:
                raise InvalidOptions(f"Unrecognized option: '{name}'")

            i += 1
            continue

        if arg.startswith("-") and arg != "-":
            j = 1
            while j < len(arg):
                ch = arg[j]

                if ch == "?":
                    config.show_help = True
                    j += 1
                    continue
                if ch == "v":
                    config.show_version = True
                    j += 1
                    continue
                if ch == "1":
                    config.short = True
                    j += 1
                    continue
                if ch == "J":
                    config.as_json = True
                    j += 1
                    continue
                if ch == "U":
                    config.transport = "udp"
                    config.force_udp = True
                    j += 1
                    continue
                if ch == "T":
                    config.transport = "tcp"
                    config.force_udp = False
                    j += 1
                    continue
                if ch == "S":
                    config.transport = "tls"
                    config.force_udp = False
                    j += 1
                    continue
                if ch == "H":
                    config.transport = "https"
                    config.force_udp = False
                    j += 1
                    continue

                if ch in {"q", "t", "n", "Z"}:
                    rest = arg[j + 1 :] or None
                    value, i = take_value(argv, i, arg, rest)
                    if ch == "q":
                        config.queries.append(canonical_name(value))
                    elif ch == "t":
                        config.qtypes.append(parse_type(value))
                    elif ch == "n":
                        config.nameservers.append(value)
                    elif ch == "Z":
                        parse_protocol_tweak(value, config.tweaks)
                    break

                raise InvalidOptions(f"Unrecognized option: '{ch}'")

            i += 1
            continue

        positionals.append(arg)
        i += 1

    for item in positionals:
        if item.startswith("@") and len(item) > 1:
            config.nameservers.append(item[1:])
            continue

        upper = item.upper()
        if upper in CLASS_BY_NAME:
            config.qclasses.append(CLASS_BY_NAME[upper])
            continue
        if upper in TYPE_BY_NAME:
            config.qtypes.append(TYPE_BY_NAME[upper])
            continue

        config.queries.append(canonical_name(item))

    if not config.qtypes:
        config.qtypes = [TYPE_BY_NAME["A"]]
    if not config.qclasses:
        config.qclasses = [CLASS_BY_NAME["IN"]]

    return config


def canonical_name(name: str) -> str:
    if not name:
        return "."
    if name.endswith("."):
        return name
    return name + "."


def read_system_nameserver() -> str:
    try:
        with open("/etc/resolv.conf", "r", encoding="utf-8") as handle:
            for line in handle:
                stripped = line.strip()
                if not stripped or stripped.startswith("#"):
                    continue
                parts = stripped.split()
                if len(parts) >= 2 and parts[0] == "nameserver":
                    return parts[1]
    except OSError as exc:
        raise SystemResolverError(str(exc)) from exc
    raise SystemResolverError("No system nameserver found")


def build_query_message(name: str, qtype: int, qclass: int, config: Config) -> bytes:
    ident = config.txid if config.txid is not None else random.randint(0, 0xFFFF)
    flags = 0x0100
    if config.tweaks.aa:
        flags |= 0x0400
    if config.tweaks.ad:
        flags |= 0x0020
    if config.tweaks.cd:
        flags |= 0x0010

    qname = encode_name(name)
    question = qname + struct.pack("!HH", qtype, qclass)

    additionals = b""
    arcount = 0
    if config.edns != "disable":
        udp_size = config.tweaks.bufsize if config.tweaks.bufsize is not None else 512
        additionals = b"\x00" + struct.pack("!HHIH", 41, udp_size, 0, 0)
        arcount = 1

    header = struct.pack("!HHHHHH", ident, flags, 1, 0, 0, arcount)
    return header + question + additionals


def encode_name(name: str) -> bytes:
    if name == ".":
        return b"\x00"
    pieces = name.rstrip(".").split(".")
    encoded = bytearray()
    for piece in pieces:
        data = piece.encode("utf-8")
        encoded.append(len(data))
        encoded.extend(data)
    encoded.append(0)
    return bytes(encoded)


def decode_name(packet: bytes, offset: int) -> tuple[str, int]:
    labels: list[str] = []
    jumped = False
    original_offset = offset
    seen: set[int] = set()

    while True:
        if offset >= len(packet):
            raise NetworkFailure("Malformed DNS packet")
        length = packet[offset]
        if length & 0xC0 == 0xC0:
            if offset + 1 >= len(packet):
                raise NetworkFailure("Malformed DNS packet")
            pointer = ((length & 0x3F) << 8) | packet[offset + 1]
            if pointer in seen:
                raise NetworkFailure("Malformed DNS packet")
            seen.add(pointer)
            if not jumped:
                original_offset = offset + 2
                jumped = True
            offset = pointer
            continue

        offset += 1
        if length == 0:
            break
        if offset + length > len(packet):
            raise NetworkFailure("Malformed DNS packet")
        labels.append(packet[offset : offset + length].decode("utf-8", "replace"))
        offset += length

    name = "." if not labels else ".".join(labels) + "."
    return name, (original_offset if jumped else offset)


def parse_header(packet: bytes) -> DNSHeader:
    if len(packet) < 12:
        raise NetworkFailure("Malformed DNS packet")
    ident, flags, qdcount, ancount, nscount, arcount = struct.unpack("!HHHHHH", packet[:12])
    return DNSHeader(ident, flags, qdcount, ancount, nscount, arcount)


def parse_response(packet: bytes) -> DNSResponse:
    header = parse_header(packet)
    offset = 12

    questions: list[DNSQuestion] = []
    for _ in range(header.qdcount):
        name, offset = decode_name(packet, offset)
        if offset + 4 > len(packet):
            raise NetworkFailure("Malformed DNS packet")
        qtype, qclass = struct.unpack("!HH", packet[offset : offset + 4])
        offset += 4
        questions.append(DNSQuestion(name, qclass, qtype))

    answers, offset = parse_rr_section(packet, offset, header.ancount)
    authorities, offset = parse_rr_section(packet, offset, header.nscount)
    additionals, offset = parse_rr_section(packet, offset, header.arcount)
    return DNSResponse(header, questions, answers, authorities, additionals)


def parse_rr_section(packet: bytes, offset: int, count: int) -> tuple[list[DNSRecord], int]:
    records: list[DNSRecord] = []
    for _ in range(count):
        name, offset = decode_name(packet, offset)
        if offset + 10 > len(packet):
            raise NetworkFailure("Malformed DNS packet")
        rtype, rclass, ttl, rdlength = struct.unpack("!HHIH", packet[offset : offset + 10])
        offset += 10
        end = offset + rdlength
        if end > len(packet):
            raise NetworkFailure("Malformed DNS packet")
        raw_rdata = packet[offset:end]
        parsed = parse_rdata(packet, offset, rdlength, rtype, rclass, ttl)
        records.append(DNSRecord(name, rtype, rclass, ttl, raw_rdata, parsed))
        offset = end
    return records, offset


def parse_char_strings(data: bytes) -> list[str]:
    strings: list[str] = []
    offset = 0
    while offset < len(data):
        length = data[offset]
        offset += 1
        strings.append(data[offset : offset + length].decode("utf-8", "replace"))
        offset += length
    return strings


def parse_rdata(packet: bytes, offset: int, length: int, rtype: int, rclass: int, ttl: int) -> Any:
    end = offset + length
    data = packet[offset:end]

    if rtype == 1 and length == 4:
        return {"address": socket.inet_ntop(socket.AF_INET, data)}
    if rtype == 28 and length == 16:
        return {"address": socket.inet_ntop(socket.AF_INET6, data)}
    if rtype == 2:
        value, _ = decode_name(packet, offset)
        return {"nameserver": value}
    if rtype == 5:
        value, _ = decode_name(packet, offset)
        return {"domain": value}
    if rtype == 12:
        value, _ = decode_name(packet, offset)
        return {"cname": value}
    if rtype == 15 and length >= 2:
        preference = struct.unpack("!H", data[:2])[0]
        exchange, _ = decode_name(packet, offset + 2)
        return {"preference": preference, "exchange": exchange}
    if rtype == 16:
        return {"messages": parse_char_strings(data)}
    if rtype == 6:
        mname, cursor = decode_name(packet, offset)
        rname, cursor = decode_name(packet, cursor)
        if cursor + 20 <= end:
            serial, refresh, retry, expire, minimum = struct.unpack("!IIIII", packet[cursor : cursor + 20])
            return {
                "mname": mname,
                "rname": rname,
                "serial": serial,
                "refresh": refresh,
                "retry": retry,
                "expire": expire,
                "minimum": minimum,
            }
        return {"mname": mname}
    if rtype == 33 and length >= 6:
        priority, weight, port = struct.unpack("!HHH", data[:6])
        target, _ = decode_name(packet, offset + 6)
        return {"priority": priority, "weight": weight, "port": port, "target": target}
    if rtype == 13:
        strings = parse_char_strings(data)
        cpu = strings[0] if strings else ""
        os_name = strings[1] if len(strings) > 1 else ""
        return {"cpu": cpu, "os": os_name}
    if rtype == 35 and length >= 4:
        order, preference = struct.unpack("!HH", data[:4])
        strings = parse_char_strings(data[4:])
        replacement = "."
        cursor = offset + 4
        for _ in range(3):
            if cursor >= end:
                break
            cursor += 1 + packet[cursor]
        if cursor <= end:
            replacement, _ = decode_name(packet, cursor)
        return {
            "order": order,
            "preference": preference,
            "flags": strings[0] if len(strings) > 0 else "",
            "service": strings[1] if len(strings) > 1 else "",
            "regex": strings[2] if len(strings) > 2 else "",
            "replacement": replacement,
        }
    if rtype == 44 and length >= 2:
        return {
            "algorithm": data[0],
            "fingerprint_type": data[1],
            "fingerprint": data[2:].hex(),
        }
    if rtype == 52 and length >= 3:
        return {
            "certificate_usage": data[0],
            "selector": data[1],
            "matching_type": data[2],
            "certificate_data": data[3:].hex(),
        }
    if rtype == 257 and length >= 2:
        tag_length = data[1]
        tag = data[2 : 2 + tag_length].decode("utf-8", "replace")
        value = data[2 + tag_length :].decode("utf-8", "replace")
        return {
            "critical": bool(data[0] & 0x80),
            "tag": tag,
            "value": value,
        }
    if rtype == 41:
        version = (ttl >> 16) & 0xFF
        flags = ttl & 0xFFFF
        options = []
        cursor = 0
        while cursor + 4 <= len(data):
            code, size = struct.unpack("!HH", data[cursor : cursor + 4])
            cursor += 4
            options.append({"code": code, "data": list(data[cursor : cursor + size])})
            cursor += size
        return {
            "udp_payload_size": rclass,
            "extended_rcode": (ttl >> 24) & 0xFF,
            "version": version,
            "flags": flags,
            "data": options,
        }
    return {"bytes": list(data)}


def resolve_nameserver(nameserver: str, transport: str) -> tuple[str, int] | str:
    if transport == "https":
        parsed = urllib.parse.urlparse(nameserver)
        if not parsed.scheme or not parsed.netloc or not parsed.path:
            raise InvalidOptions("You must pass a URL as a nameserver when using --https")
        return nameserver

    default_port = 853 if transport == "tls" else 53
    host = nameserver
    port = default_port

    if nameserver.startswith("["):
        if "]" in nameserver:
            end = nameserver.index("]")
            host = nameserver[1:end]
            rest = nameserver[end + 1 :]
            if rest.startswith(":") and rest[1:]:
                port = int(rest[1:], 10)
    elif nameserver.count(":") == 1:
        maybe_host, maybe_port = nameserver.rsplit(":", 1)
        if maybe_port.isdigit():
            host = maybe_host
            port = int(maybe_port, 10)

    return host, port


def query_udp(host: str, port: int, message: bytes, timeout: float = 5.0) -> bytes:
    addresses = socket.getaddrinfo(host, port, type=socket.SOCK_DGRAM)
    last_error: OSError | None = None
    for family, socktype, proto, _canon, sockaddr in addresses:
        try:
            with socket.socket(family, socktype, proto) as sock:
                sock.settimeout(timeout)
                sock.connect(sockaddr)
                sock.send(message)
                return sock.recv(65535)
        except OSError as exc:
            last_error = exc
    if last_error is None:
        raise NetworkFailure("No address information found")
    raise NetworkFailure(str(last_error))


def query_tcp(host: str, port: int, message: bytes, timeout: float = 5.0) -> bytes:
    addresses = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    last_error: OSError | None = None
    for family, socktype, proto, _canon, sockaddr in addresses:
        try:
            with socket.socket(family, socktype, proto) as sock:
                sock.settimeout(timeout)
                sock.connect(sockaddr)
                sock.sendall(struct.pack("!H", len(message)) + message)
                header = recv_exact(sock, 2)
                length = struct.unpack("!H", header)[0]
                return recv_exact(sock, length)
        except OSError as exc:
            last_error = exc
    if last_error is None:
        raise NetworkFailure("No address information found")
    raise NetworkFailure(str(last_error))


def query_tls(host: str, port: int, message: bytes, timeout: float = 5.0) -> bytes:
    addresses = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    context = ssl.create_default_context()
    last_error: OSError | ssl.SSLError | None = None
    for family, socktype, proto, _canon, sockaddr in addresses:
        try:
            with socket.socket(family, socktype, proto) as raw_sock:
                raw_sock.settimeout(timeout)
                raw_sock.connect(sockaddr)
                with context.wrap_socket(raw_sock, server_hostname=host) as sock:
                    sock.sendall(struct.pack("!H", len(message)) + message)
                    header = recv_exact(sock, 2)
                    length = struct.unpack("!H", header)[0]
                    return recv_exact(sock, length)
        except (OSError, ssl.SSLError) as exc:
            last_error = exc
    if last_error is None:
        raise NetworkFailure("No address information found")
    raise NetworkFailure(str(last_error))


def query_https(url: str, message: bytes, timeout: float = 5.0) -> bytes:
    request = urllib.request.Request(
        url,
        data=message,
        headers={
            "Content-Type": "application/dns-message",
            "Accept": "application/dns-message",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read()
    except urllib.error.URLError as exc:
        if exc.reason is not None:
            raise NetworkFailure(str(exc.reason)) from exc
        raise NetworkFailure(str(exc)) from exc
    except OSError as exc:
        raise NetworkFailure(str(exc)) from exc


def recv_exact(sock: socket.socket | ssl.SSLSocket, size: int) -> bytes:
    chunks = bytearray()
    while len(chunks) < size:
        piece = sock.recv(size - len(chunks))
        if not piece:
            raise NetworkFailure("Unexpected end of stream")
        chunks.extend(piece)
    return bytes(chunks)


def perform_query(message: bytes, config: Config, nameserver: str) -> DNSResponse:
    target = resolve_nameserver(nameserver, config.transport)

    if config.transport == "https":
        packet = query_https(target, message)
        return parse_response(packet)

    host, port = target
    if config.transport == "tcp":
        packet = query_tcp(host, port, message)
        return parse_response(packet)
    if config.transport == "tls":
        packet = query_tls(host, port, message)
        return parse_response(packet)

    packet = query_udp(host, port, message)
    response = parse_response(packet)
    if response.header.truncated and not config.force_udp:
        response = parse_response(query_tcp(host, port, message))
    return response


def type_label(rtype: int) -> str | int:
    return DISPLAY_TYPE_NAME_BY_CODE.get(rtype, rtype)


def class_label(rclass: int) -> str | int:
    return CLASS_NAME_BY_CODE.get(rclass, rclass)


def format_duration(seconds: int) -> str:
    if seconds < 60:
        return f"{seconds}s"
    minutes, secs = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}m{secs:02d}s"
    hours, minutes = divmod(minutes, 60)
    if hours < 24:
        return f"{hours}h{minutes:02d}m{secs:02d}s"
    days, hours = divmod(hours, 24)
    return f"{days}d{hours}h{minutes:02d}m{secs:02d}s"


def quote_text(text: str) -> str:
    escaped = text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def format_record_value(record: DNSRecord, seconds: bool) -> str:
    parsed = record.parsed
    rtype = record.rtype

    if rtype in {1, 28}:
        return parsed["address"]
    if rtype == 2:
        return quote_text(parsed["nameserver"])
    if rtype == 5:
        return quote_text(parsed["domain"])
    if rtype == 12:
        return quote_text(parsed["cname"])
    if rtype == 15:
        return f'{parsed["preference"]} {quote_text(parsed["exchange"])}'
    if rtype == 16:
        return ", ".join(quote_text(item) for item in parsed["messages"])
    if rtype == 6:
        refresh = parsed.get("refresh", 0)
        retry = parsed.get("retry", 0)
        expire = parsed.get("expire", 0)
        minimum = parsed.get("minimum", 0)
        serial = parsed.get("serial", 0)
        time_format = (lambda value: str(value)) if seconds else format_duration
        return (
            f'{quote_text(parsed.get("mname", "."))} '
            f'{quote_text(parsed.get("rname", "."))} '
            f"{serial} {time_format(refresh)} {time_format(retry)} "
            f"{time_format(expire)} {time_format(minimum)}"
        )
    if rtype == 33:
        return (
            f'{parsed["priority"]} {parsed["weight"]} '
            f'{quote_text(parsed["target"])}:{parsed["port"]}'
        )
    if rtype == 13:
        return f'{quote_text(parsed["cpu"])} {quote_text(parsed["os"])}'
    if rtype == 35:
        return (
            f'{parsed["order"]} {parsed["preference"]} '
            f'{quote_text(parsed["flags"])} {quote_text(parsed["service"])} '
            f'{quote_text(parsed["regex"])} {quote_text(parsed["replacement"])}'
        )
    if rtype == 44:
        return f'{parsed["algorithm"]} {parsed["fingerprint_type"]} {parsed["fingerprint"]}'
    if rtype == 52:
        return (
            f'{parsed["certificate_usage"]} {parsed["selector"]} '
            f'{parsed["matching_type"]} {quote_text(parsed["certificate_data"])}'
        )
    if rtype == 257:
        critical = "critical" if parsed["critical"] else "non-critical"
        return f'{quote_text(parsed["tag"])} {quote_text(parsed["value"])} ({critical})'
    if rtype == 41:
        return (
            f'{parsed["udp_payload_size"]} {parsed["extended_rcode"]} '
            f'{parsed["version"]} {parsed["flags"]} '
            f'{format_opt_list(parsed["data"])}'
        )
    return "[" + ", ".join(str(piece) for piece in parsed["bytes"]) + "]"


def format_opt_list(options: list[dict[str, Any]]) -> str:
    if not options:
        return "[]"
    rendered = []
    for option in options:
        rendered.append(f'{{"code": {option["code"]}, "data": {option["data"]}}}')
    return "[" + ", ".join(rendered) + "]"


def render_text(responses: list[DNSResponse], config: Config, duration_ms: int) -> tuple[str, int]:
    if config.short:
        values = []
        for response in responses:
            for record in response.answers:
                values.append(format_record_value(record, config.seconds))
        if values:
            return "\n".join(values), 0
        return "No results", 2

    lines: list[str] = []
    display_rows: list[tuple[str, str, str, str, str]] = []

    for response in responses:
        for record in response.answers:
            display_rows.append((
                str(type_label(record.rtype)),
                record.name if record.rtype != 41 else "",
                "" if record.rtype == 41 else ttl_label(record.ttl, config.seconds),
                " ",
                format_record_value(record, config.seconds),
            ))
        for record in response.authorities:
            display_rows.append((
                str(type_label(record.rtype)),
                record.name if record.rtype != 41 else "",
                "" if record.rtype == 41 else ttl_label(record.ttl, config.seconds),
                "A",
                format_record_value(record, config.seconds),
            ))
        for record in response.additionals:
            if record.rtype == 41 and config.edns != "show":
                continue
            display_rows.append((
                str(type_label(record.rtype)),
                record.name if record.rtype != 41 else "",
                "" if record.rtype == 41 else ttl_label(record.ttl, config.seconds),
                "+",
                format_record_value(record, config.seconds),
            ))

        if not response.answers and not response.authorities and not any(
            rec.rtype != 41 or config.edns == "show" for rec in response.additionals
        ):
            if response.header.rcode != 0:
                lines.append(f"Status: {RCODE_TEXT.get(response.header.rcode, str(response.header.rcode))}")

    if display_rows:
        type_width = max(len(row[0]) for row in display_rows)
        name_width = max(len(row[1]) for row in display_rows)
        ttl_width = max(len(row[2]) for row in display_rows)

        for rtype, name, ttl, marker, value in display_rows:
            lines.append(
                f"{rtype:>{type_width}} {name:<{name_width}} {ttl:>{ttl_width}} {marker} {value}".rstrip()
            )

    if config.show_time:
        lines.append(f"Ran in {duration_ms}ms")

    return "\n".join(lines), 0


def ttl_label(ttl: int, seconds_mode: bool) -> str:
    if seconds_mode:
        return str(ttl)
    return format_duration(ttl)


def record_to_json(record: DNSRecord) -> dict[str, Any]:
    item: dict[str, Any] = {
        "name": "" if record.rtype == 41 else record.name,
        "type": type_label(record.rtype),
        "data": record_json_data(record),
    }
    if record.rtype != 41:
        item["class"] = class_label(record.rclass)
        item["ttl"] = record.ttl
    return item


def record_json_data(record: DNSRecord) -> dict[str, Any]:
    if record.rtype == 6:
        return {"mname": record.parsed.get("mname", ".")}
    if record.rtype == 35:
        return {
            "order": record.parsed.get("order", 0),
            "flags": record.parsed.get("flags", ""),
            "service": record.parsed.get("service", ""),
            "regex": record.parsed.get("regex", ""),
            "replacement": record.parsed.get("replacement", "."),
        }
    if record.rtype == 41:
        return {
            "version": record.parsed.get("version", 0),
            "data": record.parsed.get("data", []),
        }
    return dict(record.parsed)


def responses_to_json(responses: list[DNSResponse], config: Config, duration_ms: int) -> str:
    payload: dict[str, Any] = {"responses": []}
    for response in responses:
        response_item = {
            "queries": [
                {
                    "name": question.name,
                    "class": class_label(question.qclass),
                    "type": type_label(question.qtype),
                }
                for question in response.questions
            ],
            "answers": [record_to_json(record) for record in response.answers],
            "authorities": [record_to_json(record) for record in response.authorities],
            "additionals": [
                record_to_json(record)
                for record in response.additionals
                if config.edns == "show" or record.rtype != 41
            ],
        }
        payload["responses"].append(response_item)

    if config.show_time and not config.short:
        payload["duration"] = {
            "secs": duration_ms // 1000,
            "millis": duration_ms % 1000,
        }

    return json.dumps(payload, separators=(",", ":"))


def run(config: Config) -> int:
    if config.show_help:
        print_help()
        return 0
    if config.show_version:
        print_version()
        return 0

    if not config.queries:
        print_help()
        return 3

    nameservers = list(config.nameservers)
    if not nameservers:
        if config.transport == "https":
            raise InvalidOptions("You must pass a URL as a nameserver when using --https")
        nameservers = [read_system_nameserver()]

    if config.transport == "https":
        for nameserver in nameservers:
            resolve_nameserver(nameserver, config.transport)

    responses: list[DNSResponse] = []
    started = time.perf_counter()

    for query_name in config.queries:
        for qtype in config.qtypes:
            for qclass in config.qclasses:
                for nameserver in nameservers:
                    message = build_query_message(query_name, qtype, qclass, config)
                    response = perform_query(message, config, nameserver)
                    responses.append(response)

    duration_ms = int((time.perf_counter() - started) * 1000)

    if config.as_json:
        print(responses_to_json(responses, config, duration_ms))
        return 0

    output, exit_code = render_text(responses, config, duration_ms)
    if output:
        print(output)
    return exit_code


def main(argv: list[str]) -> int:
    try:
        config = parse_args(argv)
        return run(config)
    except InvalidOptions as exc:
        print(f"dog: Invalid options: {exc}", file=sys.stderr)
        return 3
    except SystemResolverError as exc:
        print(f"Error [system]: {exc}", file=sys.stderr)
        return 4
    except NetworkFailure as exc:
        print(f"Error [network]: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

